-- NEXA: part 17 of the setup. GENERATED by scripts/build-setup-sql.sh, do not edit.
-- Run the parts in order in the Supabase SQL Editor, one after the other.
begin;


-- ===== supabase/migrations/20261204002300_news_show_v2.sql =====
-- =============================================================================
-- NEXA · 2300 · NEXA Nachrichten 2: personal news, NFTs, digressions, moods, viewers in the chat (ADR-152)
-- =============================================================================
-- * Every segment carries a "mood" for the anchor's face (newsShow.moods, one at random per script).
-- * New segments: "gossip" (personal news about real players from what they did: feed items, a failed IPO, a lost
--   job, missing for days, first or last of the rich list; bad news pay hush money), "nft" (the most expensive NFT
--   sale of the last hours) and "ramble" (he digresses; sometimes a rumour that a public figure bought a stock,
--   which lifts it a little). A fact is told once: its key is stored in news_show_used when the show airs.
-- * The order of a show puts people first: loser, gossip, company, NFT, winner, gossip, company, digression,
--   world, AI stock, hint.
-- * Made-up viewers with everyday names write in the live chat during a show (newsShow.chat.bots): their lines
--   are written at the start with the times at which they appear.
-- Idempotent: runs unchanged as supabase/updates/20261204002300_news_show_v2.sql.

alter table public.news_show_messages alter column player_id drop not null;
alter table public.news_show_messages add column if not exists bot_name text;
alter table public.news_show_messages drop constraint if exists news_show_messages_author_check;
alter table public.news_show_messages add constraint news_show_messages_author_check
  check (player_id is not null or bot_name is not null);
comment on column public.news_show_messages.bot_name is 'A made-up viewer (ADR-152); such rows have no player and may lie in the near future.';

-- One segment: script of the kind with the values filled in, a mood for the anchor, the public effect chips, the
-- internal apply list and the facts for Claude.
create or replace function public.news_show_segment(p_kind text, p_script text, p_values jsonb, p_effects jsonb, p_apply jsonb,
                                                    p_subject jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  s      jsonb := public.news_show_pick(p_script);
  v_mood text;
begin
  if s is null then
    return null;
  end if;
  select m into v_mood
    from jsonb_array_elements_text(coalesce(public.news_show_cfg() -> 'moods' -> p_script, '[]'::jsonb)) m
   order by random() limit 1;
  return jsonb_build_object(
    'kind', p_kind,
    'mood', coalesce(v_mood, 'neutral'),
    'headline', public.news_show_fill(s ->> 'headline', p_values),
    'text', public.news_show_fill(s ->> 'text', p_values),
    'effects', coalesce(p_effects, '[]'::jsonb),
    'apply', coalesce(p_apply, '[]'::jsonb),
    'subject', coalesce(p_subject, '{}'::jsonb) || jsonb_build_object('values', p_values));
end;
$$;

-- ---------------------------------------------------------------------------
-- The draft of a show
-- ---------------------------------------------------------------------------
create or replace function public.news_show_build(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.news_show_cfg();
  v_segs    jsonb := '[]'::jsonb;
  v_seg     jsonb;
  v_tip     jsonb;
  v_last    jsonb;
  v_skip_p  uuid[];
  v_skip_c  uuid[];
  r         record;
  v_bps     integer;
  v_aw      integer;
  v_dir     integer;
  v_scandal boolean;
  v_effects jsonb;
  v_apply   jsonb;
  v_max     integer := coalesce((cfg ->> 'maxSegments')::integer, 7);
  v_seen    uuid[] := '{}';
  v_n       integer := 0;
  v_win     interval;
  v_person  text;
begin
  -- who was in the last show: not again right away
  select s.segments into v_last from public.news_shows s where s.status = 'aired' order by s.airs_at desc limit 1;
  select coalesce(array_agg((x -> 'subject' ->> 'player_id')::uuid) filter (where x -> 'subject' ? 'player_id'), '{}'),
         coalesce(array_agg((x -> 'subject' ->> 'company_id')::uuid) filter (where x -> 'subject' ? 'company_id'), '{}')
    into v_skip_p, v_skip_c
    from jsonb_array_elements(coalesce(v_last, '[]'::jsonb)) x;

  -- 1. the loser of the day: roast and a consolation
  select w.entity_id as player_id, p.nickname, w.first_nw - w.last_nw as loss,
         ((w.first_nw - w.last_nw) * 10000 / w.first_nw)::integer as bps
    into r
    from (select l.entity_id, l.nw as last_nw, f.nw as first_nw
            from (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                   where entity_kind = 'player' and taken_at >= p_now - interval '45 minutes'
                   order by entity_id, taken_at desc) l
            join (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                   where entity_kind = 'player'
                     and taken_at >= p_now - make_interval(hours => coalesce((cfg #>> '{loser,windowHours}')::integer, 24))
                   order by entity_id, taken_at asc) f using (entity_id)
           where f.nw > 0) w
    join public.profiles p on p.id = w.entity_id
   where w.entity_id <> all (v_skip_p)
     and (w.first_nw - w.last_nw) * 10000 / w.first_nw >= coalesce((cfg #>> '{loser,minLossBps}')::integer, 300)
   order by (w.first_nw - w.last_nw) * 10000 / w.first_nw desc, random()
   limit 1;
  if r.player_id is not null then
    v_bps := coalesce((cfg #>> '{loser,consolationCents}')::integer, 0);
    v_seg := public.news_show_segment('loser', 'loser',
      jsonb_build_object('name', r.nickname, 'amount', public.format_eur(r.loss), 'pct', public.news_show_move(r.bps)),
      case when v_bps > 0 then jsonb_build_array(jsonb_build_object('label', '+' || public.format_eur(v_bps) || ' Trostpflaster', 'tone', 'gain'))
           else '[]'::jsonb end,
      case when v_bps > 0 then jsonb_build_array(jsonb_build_object('type', 'cash', 'player_id', r.player_id, 'cents', v_bps))
           else '[]'::jsonb end,
      jsonb_build_object('type', 'player', 'player_id', r.player_id, 'name', r.nickname));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 10)); end if;
    v_seen := v_seen || r.player_id;
  end if;

  -- 2. players' companies: a scandal or a hype
  for r in select pc.company_id, c.name, left(coalesce(nullif(btrim(pc.idea), ''), 'irgendwas mit Zukunft'), 90) as idea,
                  p.nickname as founder, pc.founder_id, sec.id as security_id, sec.ticker, c.sector_key
             from public.player_companies pc
             join public.companies c on c.id = pc.company_id
             join public.profiles p on p.id = pc.founder_id
             left join public.securities sec on sec.company_id = c.id and sec.kind = 'stock' and sec.status = 'listed'
            where pc.status = 'active' and pc.company_id <> all (v_skip_c)
            order by random()
            limit coalesce((cfg #>> '{company,count}')::integer, 2) loop
    v_n := v_n + 1;
    v_scandal := random() * 10000 < coalesce((cfg #>> '{company,scandalShareBps}')::integer, 6000);
    v_dir := case when v_scandal then -1 else 1 end;
    v_aw := public.rand_between((cfg #>> '{company,awarenessMinBps}')::integer, (cfg #>> '{company,awarenessMaxBps}')::integer);
    v_bps := public.rand_between((cfg #>> '{company,stockMinBps}')::integer, (cfg #>> '{company,stockMaxBps}')::integer);
    v_effects := jsonb_build_array(jsonb_build_object(
      'label', 'Bekanntheit ' || case when v_scandal then '−' else '+' end || public.news_show_move(v_aw),
      'tone', case when v_scandal then 'loss' else 'gain' end));
    v_apply := jsonb_build_array(jsonb_build_object('type', 'company', 'company_id', r.company_id, 'awareness_bps', v_dir * v_aw,
                                                    'scandal', v_scandal));
    if r.security_id is not null then
      v_effects := v_effects || jsonb_build_object(
        'label', r.ticker || ' ' || case when v_scandal then '−' else '+' end || public.news_show_move(v_bps),
        'tone', case when v_scandal then 'loss' else 'gain' end);
      v_apply := v_apply || jsonb_build_object('type', 'stock', 'security_id', r.security_id, 'bps', v_dir * v_bps);
    end if;
    v_seg := public.news_show_segment(case when v_scandal then 'scandal' else 'hype' end,
      case when v_scandal then 'scandal' else 'hype' end,
      jsonb_build_object('company', r.name, 'idea', r.idea, 'founder', r.founder),
      v_effects, v_apply,
      jsonb_build_object('type', 'company', 'company_id', r.company_id, 'player_id', r.founder_id, 'name', r.name,
                         'idea', r.idea, 'founder', r.founder, 'sector', r.sector_key, 'scandal', v_scandal));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', case when v_n = 1 then 30 else 70 end)); end if;
  end loop;

  -- 3. listed stocks of the AI companies
  for r in select sec.id, sec.name, sec.ticker
             from public.securities sec join public.companies c on c.id = sec.company_id
            where sec.kind = 'stock' and sec.status = 'listed' and c.is_ai
            order by random()
            limit coalesce((cfg #>> '{stock,count}')::integer, 2) loop
    v_dir := case when random() < 0.5 then 1 else -1 end;
    v_bps := public.rand_between((cfg #>> '{stock,minBps}')::integer, (cfg #>> '{stock,maxBps}')::integer);
    v_seg := public.news_show_segment('stock', case when v_dir > 0 then 'stockUp' else 'stockDown' end,
      jsonb_build_object('stock', r.name, 'move', public.news_show_move(v_bps)),
      jsonb_build_array(jsonb_build_object('label', r.ticker || ' ' || case when v_dir > 0 then '+' else '−' end || public.news_show_move(v_bps),
                                           'tone', case when v_dir > 0 then 'gain' else 'loss' end)),
      jsonb_build_array(jsonb_build_object('type', 'stock', 'security_id', r.id, 'bps', v_dir * v_bps)),
      jsonb_build_object('type', 'stock', 'name', r.name, 'ticker', r.ticker, 'up', v_dir > 0));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 100)); end if;
  end loop;

  -- 4. the world: a whole sector, or the value of open company tasks
  v_dir := case when random() < 0.5 then 1 else -1 end;
  if random() < 0.5 then
    select s.key, s.name into r from public.sectors s
     where exists (select 1 from public.securities sec where sec.sector_key = s.key and sec.kind = 'stock' and sec.status = 'listed')
     order by random() limit 1;
    if r.key is not null then
      v_bps := public.rand_between((cfg #>> '{sector,minBps}')::integer, (cfg #>> '{sector,maxBps}')::integer);
      v_seg := public.news_show_segment('sector', case when v_dir > 0 then 'sectorUp' else 'sectorDown' end,
        jsonb_build_object('sector', r.name, 'move', public.news_show_move(v_bps)),
        jsonb_build_array(jsonb_build_object('label', r.name || ' ' || case when v_dir > 0 then '+' else '−' end || public.news_show_move(v_bps),
                                             'tone', case when v_dir > 0 then 'gain' else 'loss' end)),
        jsonb_build_array(jsonb_build_object('type', 'sector', 'sector_key', r.key, 'bps', v_dir * v_bps)),
        jsonb_build_object('type', 'sector', 'name', r.name, 'up', v_dir > 0));
      if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 90)); end if;
    end if;
  else
    v_bps := public.rand_between((cfg #>> '{tasks,minBps}')::integer, (cfg #>> '{tasks,maxBps}')::integer);
    v_seg := public.news_show_segment('tasks', case when v_dir > 0 then 'tasksUp' else 'tasksDown' end,
      jsonb_build_object('move', public.news_show_move(v_bps)),
      jsonb_build_array(jsonb_build_object('label', 'Aufgaben ' || case when v_dir > 0 then '+' else '−' end || public.news_show_move(v_bps),
                                           'tone', case when v_dir > 0 then 'gain' else 'loss' end)),
      jsonb_build_array(jsonb_build_object('type', 'tasks', 'bps', v_dir * v_bps)),
      jsonb_build_object('type', 'tasks', 'up', v_dir > 0));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 90)); end if;
  end if;

  -- 5. personal news about real players: what they did in the last hours, each fact only once (news_show_used)
  v_win := make_interval(hours => coalesce((cfg #>> '{gossip,windowHours}')::integer, 24));
  v_n := 0;
  for r in
    select q.player_id, q.nickname, q.grp, q.what, q.ukey
      from (select distinct on (c.player_id) c.player_id, p.nickname, c.grp, c.what, c.ukey
              from (
                select f.actor_id as player_id,
                       case when f.kind in ('rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed') then 'bad' else 'good' end as grp,
                       public.feed_item_label(f.kind, f.payload) as what, 'fact:feed:' || f.id::text as ukey
                  from public.feed_items f
                 where f.created_at >= p_now - v_win
                   and f.kind in ('level_up', 'promoted', 'league_won', 'streak', 'company_ipo', 'company_founded', 'company_upgraded',
                                  'company_expanded', 'home_bought', 'car_bought', 'job_started', 'coin_launched', 'deal_signed',
                                  'big_trade', 'rug_pull', 'loan_defaulted', 'deal_broken', 'coin_closed')
                union all
                select pc.founder_id, 'bad', 'Börsengang von ' || c2.name || ' geplatzt', 'fact:offer:' || o.id::text
                  from public.company_share_offers o
                  join public.player_companies pc on pc.company_id = o.company_id
                  join public.companies c2 on c2.id = o.company_id
                 where o.status = 'failed' and o.kind = 'ipo' and o.closed_at >= p_now - v_win
                union all
                select j.player_id, 'bad',
                       case when j.end_reason = 'fired' then 'bei ' || c2.name || ' rausgeflogen' else 'Job bei ' || c2.name || ' hingeschmissen' end,
                       'fact:job:' || j.id::text
                  from public.player_jobs j join public.companies c2 on c2.id = j.company_id
                 where j.status = 'ended' and j.ended_at >= p_now - v_win and j.end_reason in ('fired', 'quit')
                union all
                select p2.id, 'bad',
                       'seit ' || floor(extract(epoch from (p_now - p2.last_active_at)) / 86400)::integer || ' Tagen nicht mehr gesehen',
                       'fact:gone:' || p2.id::text || ':' || floor(extract(epoch from (p_now - p2.last_active_at)) / 86400)::integer
                  from public.profiles p2
                 where p2.last_active_at < p_now - make_interval(days => coalesce((cfg #>> '{gossip,absentDays}')::integer, 3))
                   and p2.last_active_at > p_now - interval '30 days'
                union all
                select w.entity_id, case when w.pos = 1 then 'good' else 'bad' end,
                       case when w.pos = 1 then 'Platz eins der Reichenliste mit ' else 'Schlusslicht der Reichenliste mit ' end
                         || public.format_eur(w.nw),
                       'fact:rank:' || w.entity_id::text || ':' || w.pos::text || ':' || (p_now at time zone 'Europe/Berlin')::date::text
                  from (select l.entity_id, l.nw, row_number() over (order by l.nw desc) as pos, count(*) over () as n,
                               row_number() over (order by l.nw asc) as rpos
                          from (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                                 where entity_kind = 'player' and taken_at >= p_now - interval '45 minutes'
                                 order by entity_id, taken_at desc) l) w
                 where w.n >= 3 and (w.pos = 1 or w.rpos = 1)
              ) c
              join public.profiles p on p.id = c.player_id and not p.is_deactivated
             where c.player_id <> all (v_seen)
               and not exists (select 1 from public.news_show_used u where u.key = c.ukey)
             order by c.player_id, random()) q
     order by (q.player_id = any (v_skip_p)), random()
     limit coalesce((cfg #>> '{gossip,count}')::integer, 2) loop
    v_n := v_n + 1;
    v_bps := case when r.grp = 'bad' then coalesce((cfg #>> '{gossip,hushMoneyCents}')::integer, 0) else 0 end;
    v_seg := public.news_show_segment('gossip', case when r.grp = 'bad' then 'gossipBad' else 'gossipGood' end,
      jsonb_build_object('name', r.nickname, 'what', r.what),
      case when v_bps > 0 then jsonb_build_array(jsonb_build_object('label', '+' || public.format_eur(v_bps) || ' Schmerzensgeld', 'tone', 'gain'))
           else '[]'::jsonb end,
      case when v_bps > 0 then jsonb_build_array(jsonb_build_object('type', 'cash', 'player_id', r.player_id, 'cents', v_bps))
           else '[]'::jsonb end,
      jsonb_build_object('type', 'player', 'player_id', r.player_id, 'name', r.nickname, 'what', r.what,
                         'good', r.grp = 'good', 'ukey', r.ukey));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', case when v_n = 1 then 20 else 60 end)); end if;
    v_seen := v_seen || r.player_id;
  end loop;

  -- 6. the NFT market: the most expensive sale of the last hours, every sale only once
  select s.id, s.price_cents, a.title, a.creator_id, coalesce(cp.nickname, 'einem Unbekannten') as creator,
         coalesce(bp.nickname, s.buyer_ai, 'ein Unbekannter') as buyer
    into r
    from public.artwork_sales s
    join public.artworks a on a.id = s.artwork_id
    left join public.profiles cp on cp.id = a.creator_id
    left join public.profiles bp on bp.id = s.buyer_id
   where s.at >= p_now - make_interval(hours => coalesce((cfg #>> '{nft,windowHours}')::integer, 24))
     and not exists (select 1 from public.news_show_used u where u.key = 'fact:nft:' || s.id::text)
   order by s.price_cents desc, s.id desc
   limit 1;
  if r.id is not null then
    v_seg := public.news_show_segment('nft', 'nftSale',
      jsonb_build_object('name', r.creator, 'title', r.title, 'amount', public.format_eur(r.price_cents), 'buyer', r.buyer),
      '[]'::jsonb, '[]'::jsonb,
      jsonb_strip_nulls(jsonb_build_object('type', 'nft', 'player_id', r.creator_id, 'name', r.creator, 'title', r.title,
                                           'buyer', r.buyer, 'ukey', 'fact:nft:' || r.id::text)));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 40)); end if;
  end if;

  -- 7. he digresses: a rumour about a public figure and a stock (lifts it a little), or pure nonsense
  if random() * 10000 < coalesce((cfg #>> '{ramble,chanceBps}')::integer, 0) then
    v_seg := null;
    if random() * 10000 < coalesce((cfg #>> '{ramble,investShareBps}')::integer, 0)
       and jsonb_array_length(coalesce(cfg #> '{ramble,people}', '[]'::jsonb)) > 0 then
      select sec.id, sec.name, sec.ticker into r
        from public.securities sec join public.companies c on c.id = sec.company_id
       where sec.kind = 'stock' and sec.status = 'listed'
       order by random() * case when c.is_ai then 1 else 0.5 end
       limit 1;
      if r.id is not null then
        v_bps := public.rand_between((cfg #>> '{ramble,minBps}')::integer, (cfg #>> '{ramble,maxBps}')::integer);
        v_person := cfg #> '{ramble,people}' ->> least(jsonb_array_length(cfg #> '{ramble,people}') - 1,
                                                       floor(random() * jsonb_array_length(cfg #> '{ramble,people}'))::integer);
        v_seg := public.news_show_segment('ramble', 'rambleInvest',
          jsonb_build_object('person', v_person, 'stock', r.name, 'move', public.news_show_move(v_bps)),
          jsonb_build_array(jsonb_build_object('label', r.ticker || ' +' || public.news_show_move(v_bps), 'tone', 'gain')),
          jsonb_build_array(jsonb_build_object('type', 'stock', 'security_id', r.id, 'bps', v_bps)),
          jsonb_build_object('type', 'ramble', 'person', v_person, 'name', r.name, 'ticker', r.ticker));
      end if;
    end if;
    if v_seg is null then
      v_seg := public.news_show_segment('ramble', 'ramble', '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"type": "ramble"}'::jsonb);
    end if;
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 80)); end if;
  end if;

  -- 8. the winner of the day
  select w.entity_id as player_id, p.nickname, w.last_nw - w.first_nw as gain,
         ((w.last_nw - w.first_nw) * 10000 / w.first_nw)::integer as bps
    into r
    from (select l.entity_id, l.nw as last_nw, f.nw as first_nw
            from (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                   where entity_kind = 'player' and taken_at >= p_now - interval '45 minutes'
                   order by entity_id, taken_at desc) l
            join (select distinct on (entity_id) entity_id, net_worth_cents as nw from public.rich_list_snapshots
                   where entity_kind = 'player'
                     and taken_at >= p_now - make_interval(hours => coalesce((cfg #>> '{winner,windowHours}')::integer, 24))
                   order by entity_id, taken_at asc) f using (entity_id)
           where f.nw > 0) w
    join public.profiles p on p.id = w.entity_id
   where w.entity_id <> all (v_skip_p) and w.entity_id <> all (v_seen)
     and (w.last_nw - w.first_nw) * 10000 / w.first_nw >= coalesce((cfg #>> '{winner,minGainBps}')::integer, 300)
   order by (w.last_nw - w.first_nw) * 10000 / w.first_nw desc, random()
   limit 1;
  if r.player_id is not null then
    v_seg := public.news_show_segment('winner', 'winner',
      jsonb_build_object('name', r.nickname, 'amount', public.format_eur(r.gain), 'pct', public.news_show_move(r.bps)),
      '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('type', 'player', 'player_id', r.player_id, 'name', r.nickname));
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 50)); end if;
  end if;

  -- 9. the hint for the coming hour (settled by the stock news job, ADR-119)
  if public.config_jsonb('stockNews') is not null then
    select sec.id, sec.name, sec.ticker into r from public.securities sec
     where sec.kind = 'stock' and sec.status = 'listed'
       and not exists (select 1 from public.stock_tips x where x.security_id = sec.id and x.applied_at is null)
     order by random() limit 1;
    if r.id is not null then
      v_dir := case when random() < 0.5 then 1 else -1 end;
      v_bps := public.rand_between((cfg #>> '{tip,minBps}')::integer, (cfg #>> '{tip,maxBps}')::integer);
      v_tip := public.news_show_segment('tip', 'tip',
        jsonb_build_object('stock', r.name, 'move', cfg #>> array['tipWords', case when v_dir > 0 then 'up' else 'down' end]),
        jsonb_build_array(jsonb_build_object('label', r.ticker || ' ' || case when v_dir > 0 then '↑' else '↓' end || ' Tipp', 'tone', 'neutral')),
        jsonb_build_array(jsonb_build_object(
          'type', 'tip', 'security_id', r.id, 'direction', v_dir, 'bps', v_bps,
          'comes_true', random() * 10000 < coalesce((cfg #>> '{tip,reliabilityBps}')::integer, 7000),
          'lead_minutes', public.rand_between((cfg #>> '{tip,leadMinMinutes}')::integer, (cfg #>> '{tip,leadMaxMinutes}')::integer))),
        jsonb_build_object('type', 'tip', 'name', r.name, 'ticker', r.ticker, 'up', v_dir > 0));
    end if;
  end if;

  if jsonb_array_length(v_segs) = 0 and v_tip is null then
    v_seg := public.news_show_segment('world', 'filler', '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"type": "filler"}'::jsonb);
    if v_seg is not null then v_segs := v_segs || (v_seg || jsonb_build_object('ord', 5)); end if;
  end if;
  -- the order of the show: people first, the AI stock last; then at most maxSegments, the hint always last
  select coalesce(jsonb_agg((x - 'ord') order by coalesce((x ->> 'ord')::integer, 0), ord), '[]'::jsonb) into v_segs
    from jsonb_array_elements(v_segs) with ordinality t(x, ord);
  if v_tip is not null then
    select coalesce(jsonb_agg(x order by ord), '[]'::jsonb) into v_segs
      from jsonb_array_elements(v_segs) with ordinality t(x, ord) where ord <= v_max - 1;
    v_segs := v_segs || v_tip;
  else
    select coalesce(jsonb_agg(x order by ord), '[]'::jsonb) into v_segs
      from jsonb_array_elements(v_segs) with ordinality t(x, ord) where ord <= v_max;
  end if;
  return v_segs;
end;
$$;
comment on function public.news_show_build(timestamptz) is
  'Internal: the draft of a news show (ADR-150, ADR-152): loser, personal news, player companies, NFT, winner, digression, sector or tasks, AI stock, hint.';

-- News about players stand under "Spieler" in the news feed (one line of news_show_start changes).
do $do$
declare
  v_def text := pg_get_functiondef('public.news_show_start(bigint, timestamptz)'::regprocedure);
  v_old text := $t$when seg ->> 'kind' in ('loser', 'winner') then 'player'$t$;
  v_new text := $t$when seg ->> 'kind' in ('loser', 'winner', 'gossip', 'nft') then 'player'$t$;
begin
  if position(v_old in v_def) > 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- After a show started: its facts count as told, and the made-up viewers get their lines for the whole show.
create or replace function public.news_show_after_start(p_show_id bigint, p_now timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.news_show_cfg();
  bots    jsonb := public.news_show_cfg() #> '{chat,bots}';
  s       public.news_shows;
  v_intro numeric := coalesce((cfg ->> 'introSeconds')::numeric, 8);
  v_seg   numeric := greatest(1, coalesce((cfg ->> 'segmentSeconds')::numeric, 22));
  v_outro numeric := coalesce((cfg ->> 'outroSeconds')::numeric, 6);
  v_count integer;
  v_at    numeric;
  v_end   numeric;
  v_i     integer;
  v_about text;
  v_kind  text;
  v_line  text;
  v_u     double precision;
  v_n     integer := 0;
begin
  select * into s from public.news_shows where id = p_show_id;
  if s.id is null or s.status <> 'aired' then
    return 0;
  end if;
  insert into public.news_show_used (key, used_at)
  select distinct x -> 'subject' ->> 'ukey', clock_timestamp()
    from jsonb_array_elements(s.segments) x where x -> 'subject' ->> 'ukey' is not null
  on conflict (key) do update set used_at = excluded.used_at;

  if bots is null or jsonb_array_length(coalesce(bots -> 'names', '[]'::jsonb)) = 0 then
    return 0;
  end if;
  v_count := jsonb_array_length(s.segments);
  v_end := v_intro + v_count * v_seg + v_outro;
  v_at := 2 + random() * 3;
  while v_at < v_end and v_n < 200 loop
    v_i := floor((v_at - v_intro) / v_seg)::integer;
    v_about := case when v_at >= v_intro and v_i < v_count then s.segments -> v_i -> 'subject' ->> 'name' end;
    v_u := random() * 10000;
    v_kind := case when v_about is not null and v_u < coalesce((bots ->> 'aboutShareBps')::integer, 0) then 'about'
                   when v_u < coalesce((bots ->> 'aboutShareBps')::integer, 0) + coalesce((bots ->> 'angryShareBps')::integer, 5000) then 'angry'
                   else 'glaze' end;
    select replace(l, '{name}', coalesce(v_about, '')) into v_line
      from jsonb_array_elements_text(coalesce(bots -> 'lines' -> v_kind, '[]'::jsonb)) l order by random() limit 1;
    if v_line is not null and btrim(v_line) <> '' then
      insert into public.news_show_messages (player_id, bot_name, body, created_at)
      select null, n, left(v_line, 300), p_now + make_interval(secs => v_at::double precision)
        from jsonb_array_elements_text(bots -> 'names') n order by random() limit 1;
      v_n := v_n + 1;
    end if;
    v_at := v_at + public.rand_between(greatest(1, coalesce((bots ->> 'everySecondsMin')::integer, 6)),
                                       greatest(1, coalesce((bots ->> 'everySecondsMax')::integer, 14)));
  end loop;
  return v_n;
end;
$$;
comment on function public.news_show_after_start(bigint, timestamptz) is
  'Internal: marks the facts of a started show as told and writes the lines of the made-up chat viewers (ADR-152).';

-- The chat: players and made-up viewers; lines of the latter appear when their time has come.
create or replace function public.news_show_chat_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'nickname', m.nickname, 'body', m.body, 'at', m.created_at,
                                               'mine', coalesce(m.player_id = p_player, false))
                            order by m.created_at, m.id), '[]'::jsonb)
    from (select x.id, x.body, x.created_at, x.player_id, coalesce(x.bot_name, p.nickname) as nickname
            from public.news_show_messages x left join public.profiles p on p.id = x.player_id
           where x.created_at > public.game_now() - interval '75 minutes' and x.created_at <= public.game_now()
             and coalesce(x.bot_name, p.nickname) is not null
           order by x.created_at desc, x.id desc
           limit coalesce((public.news_show_cfg() #>> '{chat,history}')::integer, 60)) m;
$$;

create or replace function public.get_news_show()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.news_show_cfg();
  v_player uuid := public.require_player();
  v_now    timestamptz := public.game_now();
  v_hour   timestamptz := date_trunc('hour', public.game_now());
  v_wait   interval := make_interval(mins => coalesce((cfg ->> 'waitMinutes')::integer, 10));
  s        public.news_shows;
  u        public.news_shows;
begin
  -- I am watching
  insert into public.news_show_viewers (player_id, seen_at) values (v_player, v_now)
  on conflict (player_id) do update set seen_at = excluded.seen_at
   where public.news_show_viewers.seen_at < excluded.seen_at - interval '4 seconds';
  -- the draft may be missing when the job is late; this hour's show starts with its first viewer
  if not exists (select 1 from public.news_shows x
                  where x.airs_at = case when v_now < v_hour + v_wait then v_hour else v_hour + interval '1 hour' end) then
    perform public.news_show_run_due(v_now);
  end if;
  select * into u from public.news_shows x where x.airs_at = v_hour and x.status = 'scheduled';
  if u.id is not null and v_now < v_hour + v_wait then
    if public.news_show_start(u.id, v_now) then
      perform public.news_show_after_start(u.id, v_now);
    end if;
  end if;
  -- the show to watch: the last one that aired, while it can be replayed
  select * into s from public.news_shows x
   where x.status = 'aired'
     and x.started_at > v_now - make_interval(mins => coalesce((cfg ->> 'replayMinutes')::integer, 55))
   order by x.airs_at desc limit 1;
  select * into u from public.news_shows x where x.status = 'scheduled' and x.airs_at > v_now order by x.airs_at limit 1;
  return jsonb_build_object(
    'now', v_now,
    'next_airs_at', coalesce(u.airs_at, v_hour + interval '1 hour'),
    'viewers', (select count(*) from public.news_show_viewers v where v.seen_at > v_now - interval '20 seconds'),
    'upcoming', case when u.id is null then null else jsonb_build_object(
                  'id', u.id, 'airs_at', u.airs_at,
                  'needs_script', u.writer = 'mini' and u.ai_requested_at is null) end,
    'show', case when s.id is null then null else jsonb_build_object(
              'id', s.id, 'airs_at', s.airs_at, 'started_at', s.started_at, 'writer', s.writer,
              'segments', coalesce((select jsonb_agg(jsonb_build_object('kind', x ->> 'kind', 'mood', coalesce(x ->> 'mood', 'neutral'),
                                                                        'headline', x ->> 'headline',
                                                                        'text', x ->> 'text', 'effects', x -> 'effects')
                                                      order by ord)
                                      from jsonb_array_elements(s.segments) with ordinality t(x, ord)), '[]'::jsonb)) end,
    'chat', public.news_show_chat_json(v_player));
end;
$$;

-- Claude sees the mood and may choose another one of the known faces.
create or replace function public.news_show_script_context(p_show_id bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'show_id', s.id, 'status', s.status, 'airs_at', s.airs_at,
    'segments', coalesce((select jsonb_agg(jsonb_build_object(
                             'kind', x ->> 'kind', 'mood', coalesce(x ->> 'mood', 'neutral'),
                             'headline', x ->> 'headline', 'text', x ->> 'text',
                             'effects', (select coalesce(jsonb_agg(e ->> 'label'), '[]'::jsonb) from jsonb_array_elements(x -> 'effects') e),
                             'facts', (x -> 'subject') - 'player_id' - 'company_id' - 'ukey') order by ord)
                            from jsonb_array_elements(s.segments) with ordinality t(x, ord)), '[]'::jsonb))
    from public.news_shows s where s.id = p_show_id;
$$;

create or replace function public.store_news_show_script(p_show_id bigint, p_segments jsonb)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  s      public.news_shows;
  v_new  jsonb;
begin
  select * into s from public.news_shows where id = p_show_id for update;
  if s.id is null or s.status <> 'scheduled' or jsonb_typeof(p_segments) <> 'array'
     or jsonb_array_length(p_segments) <> jsonb_array_length(s.segments) then
    return false;
  end if;
  if exists (select 1 from jsonb_array_elements(p_segments) x
              where not public.company_ai_text_ok(x ->> 'headline', 90, true)
                 or not public.company_ai_text_ok(x ->> 'text', 420, true)) then
    return false;
  end if;
  select jsonb_agg(o.x || jsonb_build_object('headline', btrim(n.x ->> 'headline'), 'text', btrim(n.x ->> 'text'))
                       || case when n.x ->> 'mood' in ('neutral', 'shocked', 'crying', 'laughing', 'angry', 'smug', 'confused', 'proud')
                               then jsonb_build_object('mood', n.x ->> 'mood') else '{}'::jsonb end
                   order by o.ord)
    into v_new
    from jsonb_array_elements(s.segments) with ordinality o(x, ord)
    join jsonb_array_elements(p_segments) with ordinality n(x, ord) using (ord);
  update public.news_shows set segments = v_new, writer = 'claude' where id = s.id;
  return true;
end;
$$;

revoke all on function public.news_show_segment(text, text, jsonb, jsonb, jsonb, jsonb) from public, anon, authenticated;
revoke all on function public.news_show_build(timestamptz) from public, anon, authenticated;
revoke all on function public.news_show_after_start(bigint, timestamptz) from public, anon, authenticated;
revoke all on function public.news_show_chat_json(uuid) from public, anon, authenticated;
revoke all on function public.news_show_script_context(bigint) from public, anon, authenticated;
revoke all on function public.store_news_show_script(bigint, jsonb) from public, anon, authenticated;
grant execute on function public.news_show_script_context(bigint) to service_role;
grant execute on function public.store_news_show_script(bigint, jsonb) to service_role;
revoke all on function public.get_news_show() from public, anon;
grant execute on function public.get_news_show() to authenticated;

-- ===== supabase/migrations/20261204002400_share_supply.sql =====
-- =============================================================================
-- NEXA · 2400 · Stocks have a supply: nobody holds more shares than exist (ADR-153)
-- =============================================================================
-- Until now the market sold any number of shares, so players could hold more shares of a company than it has.
-- Now a buy order takes at most the free float: the company's shares minus what players hold and minus what open
-- buy orders already wait for. With no share left a buy fails with "no_shares_left" (NX129); shares come back
-- when somebody sells, and new ones when the founder runs a capital increase. Positions above the supply that
-- exist already stay as they are; they only block further buying until enough was sold.
-- Idempotent: runs unchanged as supabase/updates/20261204002400_share_supply.sql.

do $do$
declare
  v_def text := pg_get_functiondef('public.api_error(text)'::regprocedure);
begin
  if position('''no_shares_left''' in v_def) = 0 then
    v_def := replace(v_def, $q$    when 'chat_text_invalid'          then 'NX128'
$q$, $q$    when 'chat_text_invalid'          then 'NX128'
    when 'no_shares_left'             then 'NX129'
$q$);
    if position('''no_shares_left''' in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add the share supply error key by hand';
    end if;
    execute v_def;
  end if;
end;
$do$;

-- Shares (e6) of a stock that can still be bought: all shares of the company minus the players' holdings and the
-- open rest of their buy orders. Null = no limit (bonds, securities without a company).
create or replace function public.security_free_float_e6(p_security uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0,
           c.shares_outstanding * 1000000
           - coalesce((select sum(p.quantity_e6) from public.positions p
                        where p.security_id = s.id and p.status = 'open' and p.side = 'long'), 0)
           - coalesce((select sum(o.quantity_e6 - o.filled_quantity_e6) from public.orders o
                        where o.security_id = s.id and o.side = 'buy'
                          and o.status in ('pending', 'open', 'partially_filled')), 0))::bigint
    from public.securities s join public.companies c on c.id = s.company_id
   where s.id = p_security and s.kind = 'stock' and c.shares_outstanding is not null;
$$;
revoke all on function public.security_free_float_e6(uuid) from public, anon, authenticated;
grant execute on function public.security_free_float_e6(uuid) to service_role;
comment on function public.security_free_float_e6(uuid) is
  'Internal: shares (e6) of a stock still free to buy: shares outstanding minus players'' holdings and open buy orders (ADR-153).';

-- place_order(): a buy takes at most the free float (the function is otherwise unchanged).
do $do$
declare
  v_def text := pg_get_functiondef('public.place_order(uuid, text, text, text, bigint, bigint, bigint)'::regprocedure);
  v_at  text := $t$  -- minimum order value at the price it would execute or rest at$t$;
  v_new text := $t$  -- ADR-153: a stock has a supply. Buyers of one stock go one after the other, so the float cannot be oversold.
  if v_side = 'buy' and s.kind = 'stock' then
    perform 1 from public.securities x where x.id = s.id for update;
    if public.security_free_float_e6(s.id) is not null then
      if public.security_free_float_e6(s.id) < 1 then
        perform public.api_error('no_shares_left');
      end if;
      v_qty := least(v_qty, public.security_free_float_e6(s.id));
    end if;
  end if;

$t$;
begin
  if position('security_free_float_e6' in v_def) = 0 then
    if position(v_at in v_def) = 0 then
      raise exception 'place_order() has an unexpected shape; add the share supply check by hand';
    end if;
    execute replace(v_def, v_at, v_new || v_at);
  end if;
end;
$do$;

-- ===== supabase/migrations/20261204002500_more_logo_colors.sql =====
-- =============================================================================
-- NEXA · 2500 · Logos and banners with up to 16 colours like NFTs
-- =============================================================================
-- startups.logo.maxColors and startups.banner.maxColors go from 6 to 16. Grid characters are 0-9 then a-f (as for
-- artworks), so the validators build their character class from that alphabet instead of "0-(n-1)".
-- Idempotent: runs unchanged as supabase/updates/20261204002500_more_logo_colors.sql.
do $do$
declare
  v_def text;
begin
  v_def := pg_get_functiondef('public.logo_valid(jsonb)'::regprocedure);
  if position($t$'^[.0-' || (v_n - 1) || ']{'$t$ in v_def) > 0 then
    execute replace(v_def, $t$'^[.0-' || (v_n - 1) || ']{'$t$, $t$'^[.' || substr('0123456789abcdef', 1, v_n) || ']{'$t$);
  end if;
  v_def := pg_get_functiondef('public.banner_valid(jsonb)'::regprocedure);
  if position($t$'^[.0-' || (v_n - 1) || ']{'$t$ in v_def) > 0 then
    execute replace(v_def, $t$'^[.0-' || (v_n - 1) || ']{'$t$, $t$'^[.' || substr('0123456789abcdef', 1, v_n) || ']{'$t$);
  end if;
end;
$do$;

-- ===== supabase/migrations/20261204002600_friends_online_protests.sql =====
-- =============================================================================
-- NEXA · 2600 · Friends online, finished campaigns leave the news after an hour
-- =============================================================================
-- * friends_json(): every friend carries "online" (active in the last social.onlineMinutes, default 10;
--   profiles.last_active_at is refreshed by require_player at most every 5 minutes) and "last_active_at";
--   online friends come first.
-- * protests_state(): a finished campaign stays visible for protests.visibleAfterMinutes (60) instead of a day.
-- Idempotent: runs unchanged as supabase/updates/20261204002600_friends_online_protests.sql.

create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at),
                                          'online', coalesce(p.last_active_at > public.game_now() - make_interval(
                                                      mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false),
                                          'last_active_at', p.last_active_at)
                       order by coalesce(p.last_active_at > public.game_now() - make_interval(
                                  mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false) desc,
                                lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;

do $do$
declare
  v_def text := pg_get_functiondef('public.protests_state(uuid)'::regprocedure);
  v_old text := $t$x.resolved_at > now() - interval '1 day'$t$;
  v_new text := $t$x.resolved_at > now() - make_interval(mins => coalesce((public.protests_cfg() ->> 'visibleAfterMinutes')::integer, 60))$t$;
begin
  if position(v_old in v_def) > 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ===== supabase/migrations/20261204002700_missions_doable.sql =====
-- =============================================================================
-- NEXA · 2700 · Missions are always doable; one-off mission: buy a property (ADR-154)
-- =============================================================================
-- mission_doable(player, key, metric) says whether a mission can still be finished by this player. missions_assign()
-- hands out only doable missions, and an active quick or milestone mission without progress that became impossible
-- (company full, home already bought) expires and makes room for another one.
-- m_home_first becomes "Kauf dir ein Grundstück": once, fixed 2500 base XP (5000 with the global multiplier),
-- shown first among the milestones once property is unlocked.
-- Idempotent: runs unchanged as supabase/updates/20261204002700_missions_doable.sql.

create or replace function public.mission_doable(p_player uuid, p_key text, p_metric text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with co as (
    select pc.company_id, pc.ai_workers, c.max_employees, public.company_headcount(pc.company_id) as heads
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     where pc.founder_id = p_player and pc.status = 'active'
     limit 1
  ), home as (
    select h.tier, coalesce((select (t ->> 'garageSlots')::integer
                               from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) t
                              where t ->> 'key' = h.tier), 0) as garage,
           (select max(ord) from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)) as top,
           (select ord from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)
             where t ->> 'key' = h.tier) as pos
      from public.player_homes h where h.player_id = p_player
  )
  select case
    -- hiring needs a free place in the company; the "first" one only for who never had an AI worker
    when p_metric = 'ai_worker_hired' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_ai_worker' or co.ai_workers = 0))
    when p_metric = 'job_posted' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_posting'
                                      or not exists (select 1 from public.job_postings j where j.company_id = co.company_id)))
    -- property: buy one only without a home, move only below the top tier, cars only with a free garage place
    when p_metric = 'home_bought' then not exists (select 1 from home)
    when p_metric = 'home_upgraded' then exists (select 1 from home where home.pos < home.top)
    when p_metric = 'car_bought' then
      exists (select 1 from home where home.garage > (select count(*) from public.player_cars c where c.player_id = p_player))
    when p_metric in ('furniture_bought', 'furniture_placed') then exists (select 1 from home)
    -- "your first ..." only for who has not done it yet
    when p_key = 'm_first_skill' then not exists (select 1 from public.player_skills s where s.player_id = p_player)
    when p_key = 'm_first_move' then not exists (select 1 from public.company_moves m where m.started_by = p_player)
    when p_key = 'm_first_trade' then not exists (select 1 from public.trades t where t.player_id = p_player)
    when p_key = 'm_art_paint' then not exists (select 1 from public.artworks a where a.creator_id = p_player)
    when p_key = 'm_first_bond' then not exists (select 1 from public.trades t join public.securities s on s.id = t.security_id
                                                  where t.player_id = p_player and s.kind = 'bond')
    else true end;
$$;
revoke all on function public.mission_doable(uuid, text, text) from public, anon, authenticated;
grant execute on function public.mission_doable(uuid, text, text) to service_role;
comment on function public.mission_doable(uuid, text, text) is
  'Internal: whether the player can still finish a mission of this template (ADR-154).';

create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_xpscale  double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));
  -- ADR-142: mission XP grows with the level, so missions stay worth it as levels need more XP
  v_xpscale := least(public.cfg_num(v_prog, '{missionXpScaleMax}', 1),
                     1 + public.cfg_num(v_prog, '{missionXpScalePerLevel}', 0) * (v_level - 1));

  -- ADR-154: a mission nobody can finish any more (the company is full, the home is bought) makes room for another
  update public.player_missions m set status = 'expired', expires_at = least(coalesce(m.expires_at, v_now), v_now)
    from public.mission_templates mt
   where mt.key = m.template_key and m.player_id = p_player and m.status = 'active' and m.progress = 0
     and m.kind in ('quick', 'milestone') and mt.mode <> 'state'
     and not public.mission_doable(p_player, mt.key, mt.metric);

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and public.mission_doable(p_player, mt.key, mt.metric)
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              case when coalesce((t.params ->> 'fixedXp')::boolean, false)
                   then t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer
                   else round((t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))) * v_xpscale)::integer end,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

update public.mission_templates
   set title = 'Kauf dir ein Grundstück',
       description = 'Deine erste eigene Bleibe: eine Wohnung, ein Haus oder gleich mehr. Einmalig 5.000 XP.',
       xp_min = 2500, xp_max = 2500, chain_order = 1, weight = 100,
       params = params || '{"fixedXp": true}'::jsonb, updated_at = now()
 where key = 'm_home_first';

-- ===== supabase/migrations/20261204002800_accessories_pokes.sql =====
-- =============================================================================
-- NEXA · 2800 · Accessories for the pixel figure, the friends plaza, poking friends (ADR-155)
-- =============================================================================
-- * Accessories: catalogue in game_config.accessories (src/config/accessories.ts: key, name, slot, rarity,
--   priceCents, minLevel). A player buys each one once (money to the households, like furniture) and wears at most
--   one per slot. Tables player_accessories (owned) and player_accessories_worn (one row per slot); both internal.
--   RPCs get_accessories(), buy_accessory(request, key) (wears it right away), wear_accessory(request, key, wear).
--   A legendary purchase is news for the friends (feed kind accessory_bought).
-- * Others see it: get_player_card() and friends_json() return the worn keys ("accessories", back to front) and
--   friends_json() also each friend's avatar_key, so the friends plaza can draw the dressed figures.
-- * Poking: poke_friend(request, nickname) between accepted friends sends the notification friend_poke. The same
--   friend again after social.poke.cooldownMinutes (10), at most social.poke.dailyCap (30) pokes in 24 hours.
-- * Errors: accessory_unknown NX130, accessory_locked NX131, accessory_owned NX132, accessory_not_owned NX133,
--   not_friends NX134, poke_too_soon NX135, poke_daily_limit NX136.
-- Idempotent: runs unchanged as supabase/updates/20261204002800_accessories_pokes.sql.

-- ---------------------------------------------------------------------------
-- A. Error keys
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.api_error(text)'::regprocedure);
begin
  if position('''poke_daily_limit''' in v_def) = 0 then
    v_def := replace(v_def, $q$    when 'no_shares_left'             then 'NX129'
$q$, $q$    when 'no_shares_left'             then 'NX129'
    when 'accessory_unknown'          then 'NX130'
    when 'accessory_locked'           then 'NX131'
    when 'accessory_owned'            then 'NX132'
    when 'accessory_not_owned'        then 'NX133'
    when 'not_friends'                then 'NX134'
    when 'poke_too_soon'              then 'NX135'
    when 'poke_daily_limit'           then 'NX136'
$q$);
    if position('''poke_daily_limit''' in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add the accessory and poke error keys by hand';
    end if;
    execute v_def;
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- B. Notification type
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_poke', 'social', 'Angestupst', 'Ein Freund hat dich angestupst.', 'notif_friend', true, false, false, 276)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- C. Tables (internal: read and written only by the RPCs below)
-- ---------------------------------------------------------------------------
create table if not exists public.player_accessories (
  player_id        uuid not null references public.profiles (id) on delete cascade,
  accessory_key    text not null check (char_length(accessory_key) between 1 and 64),
  price_paid_cents bigint not null check (price_paid_cents >= 0),
  bought_at        timestamptz not null default now(),
  primary key (player_id, accessory_key)
);
alter table public.player_accessories enable row level security;
revoke all on public.player_accessories from public, anon, authenticated;
grant all on public.player_accessories to service_role;
comment on table public.player_accessories is
  'Accessories a player bought (ADR-155), each once. Internal (RPCs get_accessories, buy_accessory).';

create table if not exists public.player_accessories_worn (
  player_id     uuid not null,
  slot          text not null check (slot in ('back', 'body', 'face', 'head', 'hand', 'pet')),
  accessory_key text not null,
  worn_at       timestamptz not null default now(),
  primary key (player_id, slot),
  foreign key (player_id, accessory_key) references public.player_accessories (player_id, accessory_key) on delete cascade
);
create index if not exists player_accessories_worn_key_idx on public.player_accessories_worn (player_id, accessory_key);
alter table public.player_accessories_worn enable row level security;
revoke all on public.player_accessories_worn from public, anon, authenticated;
grant all on public.player_accessories_worn to service_role;
comment on table public.player_accessories_worn is
  'The accessory a player wears per slot (ADR-155): only owned ones, one per slot. Internal (RPC wear_accessory).';

create table if not exists public.friend_pokes (
  id         bigint generated always as identity primary key,
  poker_id   uuid not null references public.profiles (id) on delete cascade,
  target_id  uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index if not exists friend_pokes_poker_idx on public.friend_pokes (poker_id, created_at desc);
create index if not exists friend_pokes_target_idx on public.friend_pokes (target_id);
alter table public.friend_pokes enable row level security;
revoke all on public.friend_pokes from public, anon, authenticated;
grant all on public.friend_pokes to service_role;
comment on table public.friend_pokes is
  'Pokes between friends (ADR-155), for the pause per friend and the daily cap; older than two days is deleted. Internal.';

-- ---------------------------------------------------------------------------
-- D. Helpers
-- ---------------------------------------------------------------------------
create or replace function public.accessories_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select value from public.game_config where key = 'accessories'), '{}'::jsonb);
$$;

-- One catalogue entry by key; null if unknown
create or replace function public.accessory_item(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select x from jsonb_array_elements(coalesce(public.accessories_cfg() -> 'items', '[]'::jsonb)) x
   where x ->> 'key' = p_key
   limit 1;
$$;

-- Worn keys of a player, back to front (the order of accessories.slots)
create or replace function public.player_worn_accessories(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(w.accessory_key order by coalesce(s.ord, 99), w.slot), '[]'::jsonb)
    from public.player_accessories_worn w
    left join lateral (select x.ord from jsonb_array_elements_text(coalesce(public.accessories_cfg() -> 'slots', '[]'::jsonb))
                                          with ordinality as x(slot, ord)
                        where x.slot = w.slot) s on true
   where w.player_id = p_player;
$$;

-- The wardrobe of a player: owned keys (oldest first), worn keys, the portrait
create or replace function public.accessories_state(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'owned', coalesce((select jsonb_agg(a.accessory_key order by a.bought_at, a.accessory_key)
                         from public.player_accessories a where a.player_id = p_player), '[]'::jsonb),
    'worn', public.player_worn_accessories(p_player),
    'avatar_key', (select p.avatar_key from public.profiles p where p.id = p_player));
$$;

-- ---------------------------------------------------------------------------
-- E. RPCs: accessories
-- ---------------------------------------------------------------------------
create or replace function public.get_accessories()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.accessories_state(public.require_player());
end;
$$;
comment on function public.get_accessories() is 'RPC: the own wardrobe (ADR-155): owned and worn accessories.';

create or replace function public.buy_accessory(p_request_id uuid, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_item   jsonb;
  v_price  bigint;
  v_cash   bigint;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_accessory');
  if v_replay is not null then
    return v_replay;
  end if;
  v_item := public.accessory_item(p_key);
  if v_item is null then
    perform public.api_error('accessory_unknown');
  end if;
  if coalesce((select p.level from public.profiles p where p.id = v_player), 1) < coalesce((v_item ->> 'minLevel')::integer, 1) then
    perform public.api_error('accessory_locked');
  end if;
  v_price := (v_item ->> 'priceCents')::bigint;
  if v_price is null or v_price < 0 then
    perform public.api_error('accessory_unknown');
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if exists (select 1 from public.player_accessories a where a.player_id = v_player and a.accessory_key = p_key) then
    perform public.api_error('accessory_owned');
  end if;
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  if v_price > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'lifestyle_purchase', 'Accessoire gekauft: ' || coalesce(v_item ->> 'name', p_key),
                                   'accessory', null, 'accessory:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('accessory_key', p_key, 'price_cents', v_price));
  end if;
  insert into public.player_accessories (player_id, accessory_key, price_paid_cents) values (v_player, p_key, v_price);
  -- bought to be worn: it goes on right away (replacing what was in the slot)
  insert into public.player_accessories_worn (player_id, slot, accessory_key)
  values (v_player, v_item ->> 'slot', p_key)
  on conflict (player_id, slot) do update set accessory_key = excluded.accessory_key, worn_at = now();
  if coalesce(public.accessories_cfg() -> 'feedRarities', '[]'::jsonb) ? (v_item ->> 'rarity') then
    perform public.feed_post(v_player, 'accessory_bought',
                             jsonb_build_object('key', p_key, 'name', v_item ->> 'name', 'rarity', v_item ->> 'rarity',
                                                'price_cents', v_price),
                             'accessory:' || v_player::text || ':' || p_key);
  end if;
  return public.request_complete(v_player, p_request_id,
    public.accessories_state(v_player) || jsonb_build_object('paid_cents', v_price));
end;
$$;
comment on function public.buy_accessory(uuid, text) is
  'RPC: buys an accessory once (money to the households) and wears it (ADR-155); errors invalid_argument, '
  'accessory_unknown, accessory_locked, accessory_owned, insufficient_funds.';

create or replace function public.wear_accessory(p_request_id uuid, p_key text, p_wear boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_item   jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null or p_wear is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'wear_accessory');
  if v_replay is not null then
    return v_replay;
  end if;
  v_item := public.accessory_item(p_key);
  if v_item is null then
    perform public.api_error('accessory_unknown');
  end if;
  if not exists (select 1 from public.player_accessories a where a.player_id = v_player and a.accessory_key = p_key) then
    perform public.api_error('accessory_not_owned');
  end if;
  if p_wear then
    insert into public.player_accessories_worn (player_id, slot, accessory_key)
    values (v_player, v_item ->> 'slot', p_key)
    on conflict (player_id, slot) do update set accessory_key = excluded.accessory_key, worn_at = now();
  else
    delete from public.player_accessories_worn w where w.player_id = v_player and w.accessory_key = p_key;
  end if;
  return public.request_complete(v_player, p_request_id, public.accessories_state(v_player));
end;
$$;
comment on function public.wear_accessory(uuid, text, boolean) is
  'RPC: puts an owned accessory on (replacing the one in its slot) or takes it off (ADR-155); errors invalid_argument, '
  'accessory_unknown, accessory_not_owned.';

-- ---------------------------------------------------------------------------
-- F. RPC: poke a friend
-- ---------------------------------------------------------------------------
create or replace function public.poke_friend(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  v_them   text;
  v_cool   integer := greatest(0, coalesce(public.config_double('social', '{poke,cooldownMinutes}', 10), 10)::integer);
  v_cap    integer := greatest(1, coalesce(public.config_double('social', '{poke,dailyCap}', 30), 30)::integer);
  v_last   timestamptz;
  v_count  integer;
  v_id     bigint;
  v_lines  text[] := array[
    'Stups zurück, bevor es peinlich wird.',
    'Das war ein freundschaftlicher Stups. Vermutlich.',
    'Schau mal vorbei, dein Depot vermisst dich.',
    'Pssst! Jemand denkt an dich.',
    'Stups! Du bist dran.'];
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'poke_friend');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  if not exists (select 1 from public.friendships f
                  where f.status = 'accepted'
                    and least(f.requester_id, f.addressee_id) = least(v_player, v_other)
                    and greatest(f.requester_id, f.addressee_id) = greatest(v_player, v_other)) then
    perform public.api_error('not_friends');
  end if;
  -- one poke of the same player at a time
  select p.nickname into v_me from public.profiles p where p.id = v_player for update;
  select p.nickname into v_them from public.profiles p where p.id = v_other;
  select max(x.created_at) into v_last from public.friend_pokes x where x.poker_id = v_player and x.target_id = v_other;
  if v_last is not null and v_last > now() - make_interval(mins => v_cool) then
    perform public.api_error('poke_too_soon');
  end if;
  select count(*) into v_count from public.friend_pokes x where x.poker_id = v_player and x.created_at > now() - interval '24 hours';
  if v_count >= v_cap then
    perform public.api_error('poke_daily_limit');
  end if;
  insert into public.friend_pokes (poker_id, target_id) values (v_player, v_other) returning id into v_id;
  delete from public.friend_pokes x where x.poker_id = v_player and x.created_at < now() - interval '2 days';
  perform public.social_notify(v_other, 'friend_poke', v_me || ' hat dich angestupst! 👉',
                               v_lines[1 + floor(random() * array_length(v_lines, 1))::integer],
                               jsonb_build_object('nickname', v_me), '/players/' || v_me, 'poke:' || v_id::text);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'nickname', v_them,
    'poked_at', now(),
    'next_at', now() + make_interval(mins => v_cool),
    'left_today', greatest(0, v_cap - v_count - 1)));
end;
$$;
comment on function public.poke_friend(uuid, text) is
  'RPC: pokes a friend (ADR-155): notification friend_poke with a link to the own profile; errors invalid_argument, '
  'player_not_found, not_friends, poke_too_soon, poke_daily_limit.';

-- ---------------------------------------------------------------------------
-- G. Others see the figure: friends list and player card
-- ---------------------------------------------------------------------------
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at),
                                          'online', coalesce(p.last_active_at > public.game_now() - make_interval(
                                                      mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false),
                                          'last_active_at', p.last_active_at,
                                          'avatar_key', p.avatar_key,
                                          'accessories', public.player_worn_accessories(p.id))
                       order by coalesce(p.last_active_at > public.game_now() - make_interval(
                                  mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false) desc,
                                lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;

do $do$
declare
  v_def text := pg_get_functiondef('public.get_player_card(text)'::regprocedure);
  v_old text := $t$    'trust',           public.player_trust(p.id));$t$;
  v_new text := $t$    'accessories',     public.player_worn_accessories(p.id),
    'trust',           public.player_trust(p.id));$t$;
begin
  if position('player_worn_accessories' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'get_player_card() has an unexpected shape; add the accessories by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- H. Account reset and deletion forget the wardrobe and the pokes; the feed names the purchase
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.account_wipe(uuid, text)'::regprocedure);
  v_old text := $t$('player_homes', 'player_id'), ('trust_events', 'player_id')$t$;
  v_new text := $t$('player_homes', 'player_id'), ('trust_events', 'player_id'),
             ('player_accessories_worn', 'player_id'), ('player_accessories', 'player_id'), ('friend_pokes', 'poker_id')$t$;
begin
  if position('player_accessories_worn' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'account_wipe() has an unexpected shape; add the accessory tables by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

do $do$
declare
  v_def text := pg_get_functiondef('public.feed_item_label(text, jsonb)'::regprocedure);
  v_old text := $t$    when 'car_bought' then 'Neues Auto'$t$;
  v_new text := $t$    when 'car_bought' then 'Neues Auto'
    when 'accessory_bought' then coalesce(p_payload ->> 'name', 'Accessoire') || ' gekauft'$t$;
begin
  if position('accessory_bought' in v_def) = 0 and position(v_old in v_def) > 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.accessories_cfg()', 'public.accessory_item(text)', 'public.player_worn_accessories(uuid)',
    'public.accessories_state(uuid)', 'public.get_accessories()', 'public.buy_accessory(uuid, text)',
    'public.wear_accessory(uuid, text, boolean)', 'public.poke_friend(uuid, text)', 'public.friends_json(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_accessories()', 'public.buy_accessory(uuid, text)', 'public.wear_accessory(uuid, text, boolean)',
    'public.poke_friend(uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/migrations/20261204003500_missions_level_features.sql =====
-- =============================================================================
-- NEXA · 3500 · Harder missions with the level, missions for the new features (ADR-159)
-- =============================================================================
-- * missions_assign(): counted daily and weekly missions (and quick ones counting more than one) scale their target
--   with the level: x (1 + progression.missionCountScalePerLevel x (level - 1)), at most missionCountScaleMax.
--   Money targets keep their own scale (missionTargetScale*), XP keeps missionXpScale*.
-- * New metrics, fed by triggers so no RPC is redefined: accessory_bought, accessory_legendary, accessory_worn,
--   friend_poke, news_chat, company_chat. mission_doable() knows their preconditions; requirement "accessory".
-- * 19 new mission templates (quick, daily, weekly, milestone) for wardrobe, pokes, the news chat and the team chat.
-- Idempotent: runs unchanged as supabase/updates/20261204003500_missions_level_features.sql.

-- requirement "accessory": owns at least one accessory (wearing another one is possible)
do $do$
declare
  v_def text := pg_get_functiondef('public.mission_requirement_ok(uuid, text)'::regprocedure);
  v_old text := $t$           else false end;$t$;
  v_new text := $t$           when 'accessory' then exists (select 1 from public.player_accessories a where a.player_id = p_player)
           else false end;$t$;
begin
  if position('''accessory''' in v_def) = 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

create or replace function public.mission_doable(p_player uuid, p_key text, p_metric text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with co as (
    select pc.company_id, pc.ai_workers, c.max_employees, public.company_headcount(pc.company_id) as heads
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     where pc.founder_id = p_player and pc.status = 'active'
     limit 1
  ), home as (
    select h.tier, coalesce((select (t ->> 'garageSlots')::integer
                               from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) t
                              where t ->> 'key' = h.tier), 0) as garage,
           (select max(ord) from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)) as top,
           (select ord from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)
             where t ->> 'key' = h.tier) as pos
      from public.player_homes h where h.player_id = p_player
  )
  select case
    -- hiring needs a free place in the company; the "first" one only for who never had an AI worker
    when p_metric = 'ai_worker_hired' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_ai_worker' or co.ai_workers = 0))
    when p_metric = 'job_posted' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_posting'
                                      or not exists (select 1 from public.job_postings j where j.company_id = co.company_id)))
    -- property: buy one only without a home, move only below the top tier, cars only with a free garage place
    when p_metric = 'home_bought' then not exists (select 1 from home)
    when p_metric = 'home_upgraded' then exists (select 1 from home where home.pos < home.top)
    when p_metric = 'car_bought' then
      exists (select 1 from home where home.garage > (select count(*) from public.player_cars c where c.player_id = p_player))
    when p_metric in ('furniture_bought', 'furniture_placed') then exists (select 1 from home)
    -- ADR-159: poking needs a friend; the team chat a company; wearing something needs something to wear
    when p_metric = 'friend_poke' then exists (select 1 from public.friendships f
                                                where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id))
    when p_metric = 'company_chat' then public.mission_requirement_ok(p_player, 'team')
    when p_key = 'm_first_accessory' then not exists (select 1 from public.player_accessories a where a.player_id = p_player)
    -- "your first ..." only for who has not done it yet
    when p_key = 'm_first_skill' then not exists (select 1 from public.player_skills s where s.player_id = p_player)
    when p_key = 'm_first_move' then not exists (select 1 from public.company_moves m where m.started_by = p_player)
    when p_key = 'm_first_trade' then not exists (select 1 from public.trades t where t.player_id = p_player)
    when p_key = 'm_art_paint' then not exists (select 1 from public.artworks a where a.creator_id = p_player)
    when p_key = 'm_first_bond' then not exists (select 1 from public.trades t join public.securities s on s.id = t.security_id
                                                  where t.player_id = p_player and s.kind = 'bond')
    else true end;
$$;
revoke all on function public.mission_doable(uuid, text, text) from public, anon, authenticated;
grant execute on function public.mission_doable(uuid, text, text) to service_role;

create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_xpscale  double precision;
  v_cscale   double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));
  -- ADR-159: counted missions get harder with the level
  v_cscale := least(public.cfg_num(v_prog, '{missionCountScaleMax}', 1),
                    1 + public.cfg_num(v_prog, '{missionCountScalePerLevel}', 0) * (v_level - 1));
  -- ADR-142: mission XP grows with the level, so missions stay worth it as levels need more XP
  v_xpscale := least(public.cfg_num(v_prog, '{missionXpScaleMax}', 1),
                     1 + public.cfg_num(v_prog, '{missionXpScalePerLevel}', 0) * (v_level - 1));

  -- ADR-154: a mission nobody can finish any more (the company is full, the home is bought) makes room for another
  update public.player_missions m set status = 'expired', expires_at = least(coalesce(m.expires_at, v_now), v_now)
    from public.mission_templates mt
   where mt.key = m.template_key and m.player_id = p_player and m.status = 'active' and m.progress = 0
     and m.kind in ('quick', 'milestone') and mt.mode <> 'state'
     and not public.mission_doable(p_player, mt.key, mt.metric);

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and public.mission_doable(p_player, mt.key, mt.metric)
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   when t.mode in ('count', 'sum') and not public.mission_is_money_metric(t.metric)
                        and (v_kind in ('daily', 'weekly') or (v_kind = 'quick' and t.target_min >= 2))
                   then greatest(t.target_min, round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_cscale))::bigint
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              case when coalesce((t.params ->> 'fixedXp')::boolean, false)
                   then t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer
                   else round((t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))) * v_xpscale)::integer end,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- Mission events from the new features (triggers: the RPCs stay as they are)
-- ---------------------------------------------------------------------------
create or replace function public.mission_feature_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rarity text;
begin
  if tg_table_name = 'player_accessories' then
    perform public.mission_event(new.player_id, 'accessory_bought', 1, new.accessory_key);
    select x ->> 'rarity' into v_rarity
      from jsonb_array_elements(coalesce(public.config_jsonb('accessories', '{items}'), '[]'::jsonb)) x
     where x ->> 'key' = new.accessory_key;
    if v_rarity in ('legendary', 'mythic') then
      perform public.mission_event(new.player_id, 'accessory_legendary', 1, new.accessory_key);
    end if;
  elsif tg_table_name = 'player_accessories_worn' then
    if tg_op = 'INSERT' or new.accessory_key is distinct from old.accessory_key then
      perform public.mission_event(new.player_id, 'accessory_worn', 1, new.accessory_key);
    end if;
  elsif tg_table_name = 'friend_pokes' then
    perform public.mission_event(new.poker_id, 'friend_poke', 1, new.target_id::text);
  elsif tg_table_name = 'news_show_messages' then
    if new.player_id is not null then
      perform public.mission_event(new.player_id, 'news_chat', 1, null);
    end if;
  elsif tg_table_name = 'company_messages' then
    if new.kind = 'player' and new.author_id is not null then
      perform public.mission_event(new.author_id, 'company_chat', 1, null);
    end if;
  end if;
  return new;
end;
$$;
revoke all on function public.mission_feature_events() from public, anon, authenticated;
comment on function public.mission_feature_events() is
  'Trigger: mission events of the wardrobe, pokes, news chat and team chat (ADR-159).';

drop trigger if exists mission_events on public.player_accessories;
create trigger mission_events after insert on public.player_accessories
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.player_accessories_worn;
create trigger mission_events after insert or update of accessory_key on public.player_accessories_worn
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.friend_pokes;
create trigger mission_events after insert on public.friend_pokes
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.news_show_messages;
create trigger mission_events after insert on public.news_show_messages
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.company_messages;
create trigger mission_events after insert on public.company_messages
  for each row execute function public.mission_feature_events();

